 export function matchRoute(pattern, path) {
-  if (pattern === path) return { matched: true, params: {} };
-  return { matched: false, params: {} };
+  const patternSegments = splitPath(pattern);
+  const pathSegments = splitPath(stripQueryAndHash(path));
+  const params = {};
+
+  for (let i = 0, j = 0; i < patternSegments.length; i++, j++) {
+    const patternSegment = patternSegments[i];
+    const wildcardName = getWildcardName(patternSegment);
+
+    if (wildcardName) {
+      params[wildcardName] = pathSegments.slice(j).map(decodeSegment).join('/');
+      return { matched: true, params };
+    }
+
+    if (j >= pathSegments.length) {
+      return { matched: false, params: {} };
+    }
+
+    if (patternSegment.startsWith(':')) {
+      params[patternSegment.slice(1)] = decodeSegment(pathSegments[j]);
+      continue;
+    }
+
+    if (decodeSegment(patternSegment) !== decodeSegment(pathSegments[j])) {
+      return { matched: false, params: {} };
+    }
+  }
+
+  return {
+    matched: patternSegments.length === pathSegments.length,
+    params: patternSegments.length === pathSegments.length ? params : {},
+  };
+}
+
+function splitPath(path) {
+  if (path === '/') return [];
+  return path.replace(/^\/+|\/+$/g, '').split('/').filter(Boolean);
+}
+
+function stripQueryAndHash(path) {
+  return path.split(/[?#]/, 1)[0];
+}
+
+function decodeSegment(segment) {
+  try {
+    return decodeURIComponent(segment);
+  } catch {
+    return segment;
+  }
+}
+
+function getWildcardName(segment) {
+  if (segment === '*') return '*';
+  if (segment.startsWith('*') && segment.length > 1) return segment.slice(1);
+  if (segment.startsWith(':') && segment.endsWith('*') && segment.length > 2) {
+    return segment.slice(1, -1);
+  }
+  return null;
 }
